/* SceneModel v1 — wygenerowane ze sceny, nie edytuj ręcznie */
#{{ID}} .cg-scene { position: relative; width: 150px; height: 80px; pointer-events: none; transform: scale(var(--cg-sx, 1), var(--cg-sy, 1)); transform-origin: top left; }
#{{ID}} .cg-l, #{{ID}} .cg-i { box-sizing: border-box; }
